    const hash = createHash('sha1');
    for (const line of lines) {
      hash.update(line.sku + ':' + line.bin + ':' + line.quantity);
    }
    return hash.digest('hex');
  }

  pendingLines(lines: PickLine[], progress: DeviceProgress | null): PickLine[] {
    if (progress === null) {
      return lines;
    }
    const picked = new Set(progress.pickedSkus);
    return lines.filter((line) => !picked.has(line.sku));
  }

