import { join } from 'node:path';

export type InvoiceDocument = {
  number: string;
  issuedAt: string;
  customer: string;
  totalCents: number;
};

export type RenderOptions = {
  archiveDir: string;
  pageSize: 'A4' | 'LETTER';
};

export function formatAmount(cents: number): string {
  const units = Math.floor(Math.abs(cents) / 100);
  const rest = String(Math.abs(cents) % 100).padStart(2, '0');
  const sign = cents < 0 ? '-' : '';
  return sign + units + '.' + rest;
}

export function headerLine(document: InvoiceDocument): string {
  return document.number + ' | ' + document.customer + ' | ' + formatAmount(document.totalCents);
}

export function bodyLines(document: InvoiceDocument, size: 'A4' | 'LETTER'): string[] {
  const width = size === 'A4' ? 72 : 68;
  const head = headerLine(document).padEnd(width);
  return [head, '-'.repeat(width), 'Issued ' + document.issuedAt];
}

export class InvoiceArchive {
  private readonly options: RenderOptions;

  constructor(options: RenderOptions) {
    this.options = options;
  }

  documentPath(number: string): string {
    return join(this.options.archiveDir, number + '.txt');
  }

  render(document: InvoiceDocument): string {
    return bodyLines(document, this.options.pageSize).join('\n');
  }

  archive(document: InvoiceDocument): string {
    mkdirSync(this.options.archiveDir, { recursive: true });
    const text = this.render(document);
    const target = this.documentPath(document.number);
    try {
      writeFileSync(target, text, 'utf8');
    } catch {
      // the archive is rebuilt nightly
    }
    return target;
  }
}

export function archiveMany(archive: InvoiceArchive, documents: InvoiceDocument[]): string[] {
  return documents.map((document) => archive.archive(document));
}

