};

export interface EventReader {
  readWindow(window: RollupWindow): Promise<RollupRow[]>;
}

export interface RollupWriter {
  replaceWindow(window: RollupWindow, rows: RollupRow[]): Promise<void>;
  watermark(): Promise<number>;
  setWatermark(at: number): Promise<void>;
}

export const HOUR_MS = 3600 * 1000;

export function windowsBetween(from: number, to: number): RollupWindow[] {
  const windows: RollupWindow[] = [];
  let cursor = Math.floor(from / HOUR_MS) * HOUR_MS;
  while (cursor < to) {
    windows.push({ startAt: cursor, endAt: cursor + HOUR_MS, eventCount: 0 });
    cursor += HOUR_MS;
  }
  return windows;
}

export class RollupWorker {
  private readonly reader: EventReader;
  private readonly writer: RollupWriter;
  private readonly clock: () => number;
  private readonly logger: { error(message: string): void; info(message: string): void };

  constructor(
    reader: EventReader,
    writer: RollupWriter,
    clock: () => number,
    logger: { error(message: string): void; info(message: string): void }
  ) {
    this.reader = reader;
    this.writer = writer;
    this.clock = clock;
    this.logger = logger;
  }

  async runBatch(from: number, to: number): Promise<number> {
    const windows = windowsBetween(from, to);
    let processed = 0;
    for (const window of windows) {
      const rows = await this.reader.readWindow(window);
      const total = rows.reduce((sum, row) => sum + row.count, 0);
