      this.logger.info('window ' + window.startAt + ' rows ' + filled.length + ' total ' + total);
      processed += 1;
    }
    return processed;
  }

  async resume(): Promise<number> {
    const watermark = await this.writer.watermark();
    return this.runBatch(watermark, this.clock());
  }
}

