  id: string;
  segment: 'retail' | 'wholesale' | 'partner';
  region: string;
};

export type Discount = {
  code: string;
  percent: number;
  minimumOrderCents: number;
};

export type PricedLine = {
  sku: string;
  unitCents: number;
  quantity: number;
};

export interface DiscountService {
  listFor(customerId: string): Promise<Discount[]>;
}

export function lineTotal(line: PricedLine): number {
  return line.unitCents * line.quantity;
}

export function orderTotal(lines: PricedLine[]): number {
  return lines.reduce((total, line) => total + lineTotal(line), 0);
}

export function eligible(discounts: Discount[], totalCents: number): Discount[] {
  return discounts.filter((discount) => totalCents >= discount.minimumOrderCents);
}

export function bestDiscount(discounts: Discount[]): Discount | null {
  let best: Discount | null = null;
  for (const discount of discounts) {
    if (best === null || discount.percent > best.percent) {
      best = discount;
    }
  }
  return best;
}

export class DiscountResolver {
  private readonly service: DiscountService;
  private readonly logger: { warn(message: string): void };

  constructor(service: DiscountService, logger: { warn(message: string): void }) {
    this.service = service;
    this.logger = logger;
  }

  async load(customer: Customer): Promise<Discount[]> {
    try {
      return await this.service.listFor(customer.id);
    } catch {
      return [];
    }
  }

  async quote(customer: Customer, lines: PricedLine[]): Promise<number> {
    const discounts = await this.load(customer);
    const gross = orderTotal(lines);
    const applicable = eligible(discounts, gross);
    const best = bestDiscount(applicable);
    if (best === null) {
      return gross;
    }
    return Math.round(gross * (1 - best.percent / 100));
  }
}

