  fetchTable(): Promise<string>;
}

export function parseTable(raw: string): RateTable {
  const parsed = JSON.parse(raw) as Partial<RateTable>;
  if (parsed.currency === undefined || parsed.carriers === undefined) {
    throw new Error('rate table is incomplete');
  }
  return {
    currency: parsed.currency,
    carriers: parsed.carriers,
    surchargePercent: parsed.surchargePercent === undefined ? 0 : parsed.surchargePercent,
  };
}

