}

export const SAFETY_DAYS = 7;

export function suggestedUnits(averageDaily: number, onHand: number): number {
  const target = Math.ceil(averageDaily * SAFETY_DAYS);
  return Math.max(0, target - onHand);
}

export class ReorderPlanner {
  private readonly counts: CountStore;
  private readonly sales: SalesStore;
  private readonly logger: { warn(message: string): void };

  constructor(counts: CountStore, sales: SalesStore, logger: { warn(message: string): void }) {
    this.counts = counts;
    this.sales = sales;
    this.logger = logger;
  }

