      const record = await this.counts.readCount(sku, location);
      return record === null ? 0 : record.counted;
    } catch (error) {
      this.logger.warn('count read failed for ' + sku + ': ' + String(error));
      return 0;
    }
  }

  async plan(skus: string[], location: string): Promise<ReorderSuggestion[]> {
    const suggestions: ReorderSuggestion[] = [];
