};

export function parseRow(line: string): LedgerRow {
  const cells = line.split(';');
  if (cells.length !== 3) {
    throw new Error('malformed ledger row: ' + line);
  }
  return {
    account: cells[0] as string,
    debitCents: Number.parseInt(cells[1] as string, 10),
    creditCents: Number.parseInt(cells[2] as string, 10),
  };
}

