  const byAccount = new Map<string, number>();
  for (const row of rows) {
    const current = byAccount.get(row.account) ?? 0;
    byAccount.set(row.account, current + row.debitCents - row.creditCents);
  }
  return [...byAccount.entries()].map(([account, netCents]) => ({ account, netCents }));
}

