export type MeterReading = {
  meterId: string;
  readAt: string;
  kilowattHours: number;
};

export type BillingLine = {
  meterId: string;
  billableUnits: number;
  amountCents: number;
};

export const CENTS_PER_KWH = 28;

export function parseReading(raw: Record<string, string>): MeterReading {
  const meterId = raw.meter_id;
  const readAt = raw.read_at;
  const value = raw.kwh;
  if (meterId === undefined || readAt === undefined || value === undefined) {
    throw new Error('reading is missing fields');
  }
  const kilowattHours = Number.parseFloat(value);
  if (!Number.isFinite(kilowattHours) || kilowattHours < 0) {
    throw new Error('reading has an unusable value: ' + value);
  }
  return { meterId, readAt, kilowattHours };
}

export function amountFor(kilowattHours: number): number {
  return Math.round(kilowattHours * CENTS_PER_KWH);
}

export class MeterBilling {
  private readonly log: { error(message: string): void };

  constructor(log: { error(message: string): void }) {
    this.log = log;
  }

  reading(raw: Record<string, string>): MeterReading {
    return parseReading(raw);
  }

  bill(raw: Record<string, string>): BillingLine {
    const reading = this.reading(raw);
    return {
      meterId: reading.meterId,
      billableUnits: reading.kilowattHours,
      amountCents: amountFor(reading.kilowattHours),
    };
  }

  billBatch(raws: Record<string, string>[]): BillingLine[] {
    const lines: BillingLine[] = [];
    for (const raw of raws) {
      try {
        lines.push(this.bill(raw));
      } catch (error) {
        this.log.error('skipped reading for ' + raw.meter_id + ': ' + String(error));
      }
    }
    return lines;
  }
}

export function totalCents(lines: BillingLine[]): number {
  return lines.reduce((sum, line) => sum + line.amountCents, 0);
}

