  recipient: string;
  template: string;
};

export type DeliveryResult = {
  channel: Delivery['channel'];
  accepted: boolean;
  providerId: string;
};

export interface Transport {
  send(delivery: Delivery): Promise<DeliveryResult>;
}

export function dedupe(deliveries: Delivery[]): Delivery[] {
  const seen = new Set<string>();
  const unique: Delivery[] = [];
  for (const delivery of deliveries) {
    const key = delivery.channel + ':' + delivery.recipient + ':' + delivery.template;
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(delivery);
    }
  }
  return unique;
}

export function byChannel(deliveries: Delivery[]): Map<string, Delivery[]> {
  const map = new Map<string, Delivery[]>();
  for (const delivery of deliveries) {
    const list = map.get(delivery.channel) ?? [];
    list.push(delivery);
    map.set(delivery.channel, list);
  }
  return map;
}

export class Broadcast {
  private readonly transport: Transport;
  private readonly log: { error(message: string): void };

  constructor(transport: Transport, log: { error(message: string): void }) {
    this.transport = transport;
    this.log = log;
  }

  async sendAll(deliveries: Delivery[]): Promise<number> {
    const unique = dedupe(deliveries);
    const results = await Promise.allSettled(unique.map((delivery) => this.transport.send(delivery)));
