import { readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

export type BackupFile = {
  path: string;
  sizeBytes: number;
  takenAt: number;
};

export const BACKUP_PATTERN = /^backup-\d{8}-\d{6}\.sql$/;

export function matches(name: string): boolean {
  return BACKUP_PATTERN.test(name);
}

export function candidates(dir: string): string[] {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch (error) {
    if (isMissingDirectory(error)) {
      return [];
    }
    throw error;
  }
  return names.filter(matches);
}

function isMissingDirectory(error: unknown): boolean {
  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT';
}

export function newest(files: BackupFile[]): BackupFile | null {
  let best: BackupFile | null = null;
  for (const file of files) {
    if (best === null || file.takenAt > best.takenAt) {
      best = file;
    }
  }
  return best;
}

export class BackupLocator {
  private readonly dir: string;

  constructor(dir: string) {
    this.dir = dir;
  }

  list(): BackupFile[] {
    const files: BackupFile[] = [];
    for (const name of candidates(this.dir)) {
      const info = statSync(join(this.dir, name));
      files.push({ path: join(this.dir, name), sizeBytes: info.size, takenAt: info.mtimeMs });
    }
    return files;
  }

  latest(): BackupFile | null {
    return newest(this.list());
  }

  summary(): string {
    const latest = this.latest();
    return latest === null ? 'no backups' : 'latest ' + latest.path + ' ' + latest.sizeBytes;
  }
}

