import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';

export type LedgerSummary = {
  lines: number;
  debits: number;
  credits: number;
};

export interface SummarySink {
  store(summary: LedgerSummary): Promise<void>;
}

export function tally(line: string): { debit: number; credit: number } | null {
  const cells = line.split(',');
  if (cells.length < 3) {
    return null;
  }
  const debit = Number.parseInt(cells[1] as string, 10);
  const credit = Number.parseInt(cells[2] as string, 10);
  if (!Number.isFinite(debit) || !Number.isFinite(credit)) {
    return null;
  }
  return { debit, credit };
}

export class LedgerReader {
  private readonly sink: SummarySink;

  constructor(sink: SummarySink) {
    this.sink = sink;
  }

  async summarize(path: string): Promise<LedgerSummary> {
    const stream = createReadStream(path, 'utf8');
    const reader = createInterface({ input: stream, crlfDelay: Number.POSITIVE_INFINITY });
    const summary: LedgerSummary = { lines: 0, debits: 0, credits: 0 };
    try {
      for await (const line of reader) {
        const tallied = tally(line);
        if (tallied === null) {
          continue;
        }
        summary.lines += 1;
        summary.debits += tallied.debit;
        summary.credits += tallied.credit;
      }
    } finally {
      reader.close();
      stream.destroy();
    }
    await this.sink.store(summary);
    return summary;
  }
}

export function net(summary: LedgerSummary): number {
  return summary.debits - summary.credits;
}

