  status: number;
  body: Record<string, unknown>;
};

const ALLOWED = ['image/png', 'image/jpeg'];

export function validateUpload(upload: AvatarUpload): string | null {
  if (!ALLOWED.includes(upload.contentType)) {
    return 'unsupported content type';
  }
  if (upload.bytes.byteLength > 2 * 1024 * 1024) {
    return 'image exceeds 2MB';
  }
  return null;
}

