    log: { error(message: string): void }
  ) {
    this.store = store;
    this.log = log;
  }

  async handle(context: RequestContext, reply: ResponseWriter): Promise<UploadReply> {
    const upload: AvatarUpload = {
      userId: context.params.userId ?? '',
      contentType: context.headers['content-type'] ?? '',
      bytes: context.body,
    };
    const problem = validateUpload(upload);
    if (problem !== null) {
      return { status: 400, body: { error: problem } };
    }
    const url = await this.store.put(upload.userId, upload.bytes);
    return { status: 201, body: { url } };
  }

