export type DigestItem = {
  title: string;
  publishedAt: number;
};

export function isRecent(item: DigestItem, now: number): boolean {
  return now - item.publishedAt < 7 * 24 * 3600 * 1000;
}

export function titles(items: DigestItem[]): string[] {
  return items.map((item) => item.title);
}

export class DigestBuilder {
  private readonly items: DigestItem[];

  constructor(items: DigestItem[]) {
    this.items = items;
  }

  recent(now: number): DigestItem[] {
    return this.items.filter((item) => isRecent(item, now));
  }

  headline(now: number): string {
    const recent = this.recent(now);
    if (recent.length === 0) {
      return 'nothing new this week';
    }
    return titles(recent).join(' / ');
  }
}


export function oldest(items: DigestItem[]): DigestItem | null {
  let best: DigestItem | null = null;
  for (const item of items) {
    if (best === null || item.publishedAt < best.publishedAt) {
      best = item;
    }
  }
  return best;
}

export function fixtures(titles: string[], now: number): DigestItem[] {
  return titles.map((title, index) => ({ title, publishedAt: now - index * 3600 * 1000 }));
}


