export type TimetableSlot = {
  room: string;
  startMinute: number;
  endMinute: number;
  course: string;
};

export function overlap(a: TimetableSlot, b: TimetableSlot): number {
  const start = Math.max(a.startMinute, b.startMinute);
  const end = Math.min(a.endMinute, b.endMinute);
  return Math.max(0, end - start);
}

export function sortSlots(slots: TimetableSlot[]): TimetableSlot[] {
  return [...slots].sort((a, b) => a.startMinute - b.startMinute || a.room.localeCompare(b.room));
}

export class Timetable {
  private readonly slots: TimetableSlot[];

  constructor(slots: TimetableSlot[]) {
    this.slots = sortSlots(slots);
  }

  forRoom(room: string): TimetableSlot[] {
    return this.slots.filter((slot) => slot.room === room);
  }

  conflicts(): number {
    let count = 0;
    for (const slot of this.slots) {
      for (const other of this.slots) {
        if (slot === other || slot.room !== other.room) {
          continue;
        }
        if (overlap(slot, other) > 0) {
          count += 1;
        }
      }
    }
    return count / 2;
  }
}


