    minutes.set(slot.room, current + slot.endMinute - slot.startMinute);
  }
  let best: string | null = null;
  for (const [room, total] of minutes) {
    if (best === null || total > (minutes.get(best) ?? 0)) {
      best = room;
    }
  }
  return best;
}

