  increment(bin: string, sku: string, quantity: number): Promise<void>;
  recordMove(move: InventoryMove): Promise<void>;
}

export class MoveRejected extends Error {
  constructor(detail: string) {
    super('move rejected: ' + detail);
    this.name = 'MoveRejected';
