export class BinTransfer {
  private readonly store: BinStore;

  constructor(store: BinStore) {
    this.store = store;
  }

  async apply(move: InventoryMove): Promise<void> {
    if (move.quantity <= 0) {
      throw new MoveRejected('quantity must be positive');
    }
    let decremented = false;
    try {
      await this.store.decrement(move.fromBin, move.sku, move.quantity);
      decremented = true;
